package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"sort"
)

const (
	MOD     = 998244353
	ROOT    = 15311432
	INVROOT = 469870224
)

func bitReverse(n, k int) int {
	return int(bits.Reverse32(uint32(n)) >> (32 - k))
}

func modPow(a, p int64) int64 {
	res := int64(1)
	a %= MOD
	for p > 0 {
		if p&1 == 1 {
			res = (res * a) % MOD
		}
		a = (a * a) % MOD
		p >>= 1
	}
	return res
}

func modInv(a int64) int64 {
	return modPow(a, MOD-2)
}

func numberTheoreticTransform(coef []int64, k int, inverse bool) {
	baseRoot := ROOT
	if inverse {
		baseRoot = INVROOT
	}
	root := modPow(int64(baseRoot), modPow(2, int64(23-k)))
	roots := make([]int64, k)
	roots[k-1] = root
	for i := k - 1; i > 0; i-- {
		roots[i-1] = (roots[i] * roots[i]) % MOD
	}

	for s := 0; s < k; s++ {
		len_ := 1 << s
		for st := 0; st < len(coef); st += 2 * len_ {
			curRoot := int64(1)
			for j := st; j < st+len_; j++ {
				t := (curRoot * coef[j+len_]) % MOD
				u := coef[j]
				coef[j] = (u + t) % MOD
				coef[j+len_] = (u - t + MOD) % MOD
				curRoot = (roots[s] * curRoot) % MOD
			}
		}
	}
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	n := scanInt(scanner) / 2
	scanner.Scan()
	m := scanInt(scanner)

	nums := make([]int, m)
	for i := 0; i < m; i++ {
		scanner.Scan()
		nums[i] = scanInt(scanner)
	}
	sort.Ints(nums)

	minSize := n*nums[m-1] + 2
	k := 0
	size := 1
	for size < minSize {
		size *= 2
		k++
	}

	a := make([]int64, size)
	for i := 0; i < m; i++ {
		a[bitReverse(nums[i], k)] = 1
	}

	numberTheoreticTransform(a, k, false)

	for i := 0; i < size; i++ {
		a[i] = modPow(a[i], int64(n))
	}

	temp := make([]int64, size)
	for i := 0; i < size; i++ {
		temp[bitReverse(i, k)] = a[i] % MOD
	}
	a = temp

	numberTheoreticTransform(a, k, true)

	ans := int64(0)
	for i := 0; i < size; i++ {
		ans = (ans + a[i]*a[i]) % MOD
	}

	multiplier := modInv(int64(size))
	ans = (ans * multiplier) % MOD
	ans = (ans * multiplier) % MOD
	fmt.Println(ans)
}

func scanInt(scanner *bufio.Scanner) int {
	var x int
	fmt.Sscan(scanner.Text(), &x)
	return x
}

